//
// What e8-themes-select shows of each theme in this repository without
// loading it, written by tools/port-themes.el from the faces Emacs gives
// the theme upstream. Do not edit: run `make port` again.

/** A theme of this repository, as the chooser lists it. */
export interface ThemeEntry {
  name: string;
  /** The collection it is filed under: Modus, Ef, Doom, ... */
  collection: string;
  doc: string;
  dark: boolean;
  background: string;
  foreground: string;
  /** Its colours for keywords, strings, functions, types, constants and comments. */
  swatches: string[];
  /** Contrast against its background, as WCAG measures it: text, code at worst, comments. */
  contrast: { text: number; code: number; comments: number };
  /** Where it comes from. */
  /** Where it comes from, sources.json says more: its package and version, the commit it was ported at, its licence and authors, and the theme it is after. */
  source: { package: string; version: string; commit: string; licence: string; authors: string[]; original?: string };
}

